import{_ as o,a0 as u,w as p,s as d,ao as r,I as i,x as t,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const X=JSON.parse('{"title":"對決：Ubuntu 14.04 LTS 大戰 Windows XP | LCTT x X-CMD","titleTemplate":false,"description":"對決：Ubuntu 14.04 LTS 大戰 Windows XP | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"對決：Ubuntu 14.04 LTS 大戰 Windows XP | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"對決：Ubuntu 14.04 LTS 大戰 Windows XP | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Ubuntu 14.04 LTS vs. Windows XP--Pros and Cons","title":"對決：Ubuntu 14.04 LTS 大戰 Windows XP","tag":"201403","desc":""},"relativePath":"201403/Ubuntu 14.04 LTS vs. Windows XP--Pros and Cons.md","filePath":"[post].md"}'),l={name:"201403/Ubuntu 14.04 LTS vs. Windows XP--Pros and Cons.md"};function m(b,n,w,P,T,h){const s=u("Link");return p(),d("div",null,[n[11]||(n[11]=r('<h1 id="對決-ubuntu-14-04-lts-大戰-windows-xp" tabindex="-1">對決：Ubuntu 14.04 LTS 大戰 Windows XP <a class="header-anchor" href="#對決-ubuntu-14-04-lts-大戰-windows-xp" aria-label="Permalink to “對決：Ubuntu 14.04 LTS 大戰 Windows XP”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-14-04-LTS-vs-Windows-XP-Pros-and-Cons-430084-2.jpg" alt=""></p><p><strong>越來越多的人期待着 Ubuntu 14.04 LTS (Trusty Tahr) 的發佈，並希望她能在不改變用户習慣的前提下替代 Windows XP。 因此我們將在本文嘗試給大家分析下這個兩個系統的優缺點。</strong></p><p>很多 Windows XP 用户在微軟宣佈四月份後即將停止對他們的操作系統提供安全更新後作出改變。他們像大多數改用 Linux 的用户一樣，有着大量的系統操作和兼容性方面各式各樣的問題。而事實是這些原 XP 用户可能顧慮太多了，理由如下：</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>如果你在一生中哪怕就裝過一次 Windows，祝賀你，因為你已經知道該如何安裝 Ubuntu 這類的系統了。Ubuntu 為用户提供了一個很直觀而且沒有太多複雜選項的安裝界面。</p><p>唯一可能會使你疑惑的就是系統分區時出現的大量陌生詞彙了，比如“交換空間(swap)”和“EXT4文件系統”。不過好消息是在 Linux 下你或許永遠不需要多個分區了。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-14-04-LTS-vs-Windows-XP-Pros-and-Cons-430084-3.jpg" alt=""></p><p><em>Ubuntu 安裝</em></p><h3 id="驅動" tabindex="-1">驅動 <a class="header-anchor" href="#驅動" aria-label="Permalink to “驅動”">​</a></h3><p>Windows 用户需要為新的硬件安裝驅動，比方説聊天時用的攝像頭。 某些驅動或許會由系統提供，但大多數的仍需要手動安裝。</p><p>在 Ubuntu 的驅動問題上，唯一可能需要擔心的就是顯卡驅動了。 首先你可能不清楚應該從哪裏改變現有驅動，而安裝一個新的驅動可能需要一些調整。 然而這剛好是你學習如何添加一個 PPA 源以及更新你的軟件包的好時機，而且這些操作都輕而易舉。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-14-04-LTS-vs-Windows-XP-Pros-and-Cons-430084-4.jpg" alt=""></p><p><em>安裝私有驅動</em></p><h3 id="主界面" tabindex="-1">主界面 <a class="header-anchor" href="#主界面" aria-label="Permalink to “主界面”">​</a></h3><p>Ubuntu 在整體界面上還是和 Windows XP 有些區別的。儘管她更直觀，但總有些偷懶的用户還是會放棄探索如何使用這個新系統的精彩時光。</p><p>不過呢 Ubuntu 依然可以為這些“懶”用户們提供幾種看起來更像 Windows XP 的衍生版本，比如 Xubuntu 和 Lubuntu。 她們都是基於 Ubuntu 的而且提供基本相同的軟件。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-14-04-LTS-vs-Windows-XP-Pros-and-Cons-430084-5.jpg" alt=""></p><p><em>Ubuntu 桌面</em></p><h3 id="應用與安全" tabindex="-1">應用與安全 <a class="header-anchor" href="#應用與安全" aria-label="Permalink to “應用與安全”">​</a></h3><p>或許你會覺得在 Windows XP 上安裝程序很容易。 不是麼？就雙擊一個安裝程序，然後狂按下一步（包括壓根沒人讀的那份最終用户許可協議），一個程序就這麼裝上了。</p><p>Ubuntu 下事情其實更簡單。只要打開 Ubuntu 軟件中心然後搜索你想要的應用，最後輕輕按下安裝，一切搞定！</p><p>有些情況下在 Windows XP 上安裝程序會很危險，尤其是在微軟終止提供安全補丁以後。 在 Ubuntu 上你將很難再見到你身邊的那堆病毒和流氓軟件，即使有病毒在 Linux 上出現也將非常短命。 只要程序有任何一個問題出現，立即就會有開發人員釋出補丁並修復。</p><p>不過呢，在 Ubuntu 上你也許不大可能會找全你在 Windows XP 上曾經用過的所有軟件。 但大部分知名軟件商都會提供 Linux 版本，不但如此你還可以在 Ubuntu 上找尋更多的相似軟件予以替代。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-14-04-LTS-vs-Windows-XP-Pros-and-Cons-430084-6.jpg" alt=""></p><p><em>使用 Ubuntu 軟件中心安裝應用</em></p><h3 id="遊戲" tabindex="-1">遊戲 <a class="header-anchor" href="#遊戲" aria-label="Permalink to “遊戲”">​</a></h3><p>也許 Windows XP 看起來更適合玩遊戲，但事實是大多數遊戲開發者將放棄去兼容一個即將消亡的系統。 而且 Valve 將進一切力量去支持 Linux 平台並將整個遊戲產業推向這個方向。</p><p>Linux 版 Steam 僅推出一年時間就有 500 多個遊戲上線而且這個趨勢沒有任何下降的跡象。 再過幾年，在遊戲方面 Linux 平台必將趕超 Windows。 所以現在就開始熟悉 Ubuntu 吧，如果你是個出色的玩家，就絕不應該放棄這個機會。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-14-04-LTS-vs-Windows-XP-Pros-and-Cons-430084-7.jpg" alt=""></p><p><em>Linux 版《傳送門 2》</em></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>如果你是一個 Windows XP 用户但對使用 Linux 和 Ubuntu 有任何顧慮，建議你在升級到 Windows 7 或 8 之前再三考慮。 Linux 有所有你需要的功能，沒有任何理由不去使用一個基於她的操作系統。</p><hr>',34)),i("p",null,[n[1]||(n[1]=t("via: ",-1)),a(s,{href:"http://news.softpedia.com/news/Ubuntu-14-04-LTS-vs-Windows-XP-Pros-and-Cons-430084.shtml"},{default:e(()=>[...n[0]||(n[0]=[t("http://news.softpedia.com/news/Ubuntu-14-04-LTS-vs-Windows-XP-Pros-and-Cons-430084.shtml",-1)])]),_:1})]),i("p",null,[n[4]||(n[4]=t("譯者：",-1)),a(s,{href:"https://github.com/vizv"},{default:e(()=>[...n[2]||(n[2]=[t("VizV",-1)])]),_:1}),n[5]||(n[5]=t(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:e(()=>[...n[3]||(n[3]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[8]||(n[8]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原創翻譯，",-1)),a(s,{href:"http://linux.cn/"},{default:e(()=>[...n[7]||(n[7]=[t("Linux中國",-1)])]),_:1}),n[10]||(n[10]=t(" 榮譽推出",-1))])])}const f=o(l,[["render",m]]);export{X as __pageData,f as default};
